    };

    const start = () => {
      if (running) return;
      running = true;
      launchFirework();
      animate();
    };

    const stop = () => {
      running = false;
      clearTimeout(launchTimeoutId);
      cancelAnimationFrame(frameId);
    };

    const still = () => {
      if (running) return;
      fireworks.length = 0;
      explosions.length = 0;
      const options = optionsRef.current;
      for (let i = 0; i < 3; i++) {
        const firework = createFirework(
          maxX * (0.25 + i * 0.25),
          maxY * rand(0.25, 0.45),
          0,
          getColor(options.color),
          0,
          0,
          options.particleSpeed,
          options.particleSize,
          handleExplosion,
        );
        firework.explode();
      }
      for (let i = 0; i < 25; i++) {
        for (const particle of explosions) particle.update();
      }
