        scale: [1, 0.92, 1.05, 0.98, 1],
        rotate: [0, -3, 3, -1.5, 0],
        y: [0, -1, 0.5, 0],
        transition: { duration: 0.5, ease: 'easeInOut' },
      },
    },
    back: {},
    path: {},
  } satisfies Record<string, Variants>,
  bounce: {
    group: {
      initial: {
        scale: 1,
        y: 0,
      },
      animate: {
        scale: [1, 0.9, 1.06, 0.97, 1],
        y: [0, -1.5, 0.5, 0],
        transition: { duration: 0.5, ease: 'easeInOut' },
      },
    },
    back: {},
    path: {},
  } satisfies Record<string, Variants>,
  fill: {
    group: {
      initial: {
        scale: 1,
        rotate: 0,
        y: 0,
      },
      animate: {
        scale: [1, 0.92, 1.05, 0.98, 1],
        rotate: [0, -3, 3, -1.5, 0],
        y: [0, -1, 0.5, 0],
        transition: { duration: 0.5, ease: 'easeInOut' },
      },
    },
    back: {},
    path: {
      initial: {
        fill: 'currentColor',
        fillOpacity: 0,
      },
      animate: {
        fillOpacity: 1,
        transition: { delay: 0.15 },
      },
    },
  } satisfies Record<string, Variants>,
} as const;

function IconComponent({ size, ...props }: FolderProps) {
  const { controls } = useAnimateIconContext();
