      strokeWidth={2}
      strokeLinecap="round"
      strokeLinejoin="round"
      {...props}
    >
      <motion.g variants={variants.group} initial="initial" animate={controls}>
        <motion.path
          d={CLOSED_FRONT}
          variants={variants.back}
          initial="initial"
          animate={controls}
        />
        <motion.path
          d={CLOSED_FRONT}
          variants={variants.path}
          initial="initial"
          animate={controls}
