          scale: [1, 0.88, 0.88, 0.88, 0.88, 1],
          transition: { duration: 0.7, ease: 'easeInOut' },
        },
      },
    };

    for (let i = 1; i <= 2; i++) {
      animation[`wave${i}`] = {
        initial: { opacity: 1, scale: 1 },
        animate: {
          opacity: 0,
          scale: 0,
          transition: {
            opacity: {
              duration: 0.2,
              ease: 'easeInOut',
              repeat: 1,
              repeatType: 'reverse',
              repeatDelay: 0.2,
              delay: 0.2 * (i - 1),
