        d="M17.84 7.17a4 4 0 0 0-5.66 0"
        variants={variants.path1}
        initial="initial"
        animate={controls}
      />
      <motion.path
        d="M20.66 4.34a8 8 0 0 0-11.31 0"
        variants={variants.path2}
        initial="initial"
        animate={controls}
      />
      <motion.path
        d="M6.01 18H6"
