        d="M10.01 18H10"
        variants={variants.path4}
        initial="initial"
        animate={controls}
      />
      <motion.path
        d="M15 10v4"
        variants={variants.path5}
        initial="initial"
        animate={controls}
      />
    </motion.svg>
  );
}

function Router(props: RouterProps) {
